<script setup lang="ts">
import type { ApiEnvelope, User } from '~/types/api'
definePageMeta({ layout: 'dashboard', middleware: 'auth' }); useSeoPage('Profile', 'Manage your account details and password.', '/dashboard/profile')
const { user } = useAuth(); const profile = reactive({ name: user.value?.name || '', email: user.value?.email || '' }); const password = reactive({ current_password: '', password: '', password_confirmation: '' }); const message = ref(''); const error = ref(''); const { request } = useApi()
async function saveProfile() { message.value = ''; error.value = ''; try { const response = await request<ApiEnvelope<User>>('profile', { method: 'PATCH', body: profile }); user.value = response.data; message.value = response.message || 'Profile updated.' } catch (e: any) { error.value = Object.values(e?.data?.errors || {}).flat().join(' ') || e?.data?.message } }
async function savePassword() { message.value = ''; error.value = ''; try { const response = await request<ApiEnvelope<null>>('profile/password', { method: 'PUT', body: password }); message.value = response.message || 'Password updated.'; Object.assign(password, { current_password: '', password: '', password_confirmation: '' }) } catch (e: any) { error.value = Object.values(e?.data?.errors || {}).flat().join(' ') || e?.data?.message } }
</script>
<template><div class="max-w-3xl"><p class="eyebrow">Account</p><h1 class="mt-2 text-3xl font-black">Profile</h1><p v-if="message" class="mt-6 rounded-xl bg-teal-300/10 p-4 text-teal-200" role="status">{{ message }}</p><p v-if="error" class="mt-6 rounded-xl bg-rose-400/10 p-4 text-rose-300" role="alert">{{ error }}</p><form class="surface mt-8 grid gap-5 p-6" @submit.prevent="saveProfile"><h2 class="text-xl font-bold">Personal information</h2><div><label class="label" for="name">Name</label><input id="name" v-model="profile.name" class="input" required></div><div><label class="label" for="email">Email</label><input id="email" v-model="profile.email" class="input" type="email" required><p class="mt-2 text-xs text-slate-500">Changing email requires verification again.</p></div><button class="btn-primary w-fit">Save profile</button></form><form class="surface mt-6 grid gap-5 p-6" @submit.prevent="savePassword"><h2 class="text-xl font-bold">Change password</h2><div><label class="label" for="current-password">Current password</label><input id="current-password" v-model="password.current_password" class="input" type="password" required></div><div><label class="label" for="new-password">New password</label><input id="new-password" v-model="password.password" class="input" type="password" required></div><div><label class="label" for="confirm-password">Confirm new password</label><input id="confirm-password" v-model="password.password_confirmation" class="input" type="password" required></div><button class="btn-primary w-fit">Update password</button></form></div></template>
